(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_encourage','encourage','verb','to give someone support, confidence or hope so that they do something','[{"senseId":"encourage_1","meaning":"to give someone support, confidence or hope so that they do something","acceptedParaphrases":["support","give someone confidence to do something"],"masteryContexts":[{"contextId":"u10_11_encourage_meaning","text":"Good teachers encourage shy students to share their ideas.","meaning":"to give someone the confidence to do something","wrongMeanings":["to stop someone from doing something","to punish someone for doing something","to do something instead of someone"]},{"contextId":"u10_11_encourage_paraphrase","text":"The new bike lanes are meant to encourage more people to cycle to work.","meaning":"to make an action more likely to happen","wrongMeanings":["to make an action less likely to happen","to make an action illegal","to make an action more expensive"]}],"situationDistractors":["A coach told a player she would never be good enough for the team.","A mother told her son to stop playing the drums.","A teacher ignored a student who raised her hand.","A coach shouted at a player for making a mistake.","A father said his daughter’s idea was silly.","A teacher told a boy to sit down and stop talking."],"gapDistractors":[{"contextId":"u10_11_encourage_gap_1","answer":"encourage","wrong":["succeed","reflect","communicate"]},{"contextId":"u10_11_encourage_gap_2","answer":"encourage","wrong":["succeed","contribute","reflect"]},{"contextId":"u10_11_encourage_gap_3","answer":"encourage","wrong":["succeed","contribute","develop"]}],"spellingErrors":["encorage","incourage","encurage","encourrage","encouradge","encourag"],"wordFamilyForms":[{"form":"encourage","partOfSpeech":"verb","example":"Good coaches encourage players to learn from mistakes.","pedagogicallyUseful":true},{"form":"encouragement","partOfSpeech":"noun","example":"With a little encouragement, she joined the choir.","pedagogicallyUseful":true,"altExample":"The crowd shouted words of encouragement to the runners."},{"form":"encouraging","partOfSpeech":"adjective","example":"The first test results are very encouraging.","pedagogicallyUseful":true,"altExample":"It is encouraging that more girls are studying science."}],"masteryPassages":[{"passageId":"u10_11_encourage_passage_1","contextId":"u10_11_encourage_gap_1","text":"Leo wanted to give up the piano after a difficult lesson. His teacher told him he was improving and tried to ____ him to keep practising.","answer":"encourage"},{"passageId":"u10_11_encourage_passage_2","contextId":"u10_11_encourage_gap_2","text":"The city has built hundreds of kilometres of cycle lanes. Officials hope this will ____ more people to leave their cars at home.","answer":"encourage"}],"contextDependentParaphrases":[],"wrongParaphrases":["discourage","criticise","ignore"],"misleadingDistractors":["to stop someone from doing something","to criticise someone in front of others","to ignore what someone is trying to do"],"teacherNote":"Verb: to give support or confidence, or to make something more likely (encourage someone to do something, encourage reading). Pattern: encourage + object + to-infinitive. Opposite: discourage. The noun encouragement and the adjective encouraging are taught in the Word Family pathway."}]'::jsonb,'["encouragement","encouraging"]'::jsonb,'["encourage someone to","strongly encourage","encourage reading"]'::jsonb,'live'),
('vocab_reflect_10','reflect','verb','to think carefully and seriously about something, especially something you have done','[{"senseId":"reflect_10_1","meaning":"to think carefully and seriously about something, especially something you have done","acceptedParaphrases":["think carefully about","consider seriously"],"masteryContexts":[{"contextId":"u10_12_reflect_10_meaning","text":"Take a few minutes to reflect on how well your group worked together.","meaning":"to think carefully about an experience","wrongMeanings":["to forget an experience quickly","to complain about an experience","to write a story about an experience"]},{"contextId":"u10_12_reflect_10_paraphrase","text":"Your excellent exam results reflect the hard work you have done all year.","meaning":"to show or be a sign of something","wrongMeanings":["to hide or cover something","to change or reduce something","to cause or create something"]}],"situationDistractors":["A boy threw his test paper in the bin without looking at it.","A girl rushed out of the classroom as soon as the bell rang.","A student copied a friend’s answers without reading them.","A boy rushed to the next activity without a thought.","A girl ate her lunch while running for the bus.","A student threw away his feedback without reading it."],"gapDistractors":[{"contextId":"u10_12_reflect_10_gap_1","answer":"reflect","wrong":["succeed","contribute","encourage"]},{"contextId":"u10_12_reflect_10_gap_2","answer":"reflect","wrong":["succeed","encourage","communicate"]},{"contextId":"u10_12_reflect_10_gap_3","answer":"reflect","wrong":["succeed","encourage","develop"]}],"spellingErrors":["reflet","reflact","relfect","reflecct","refelct","reflekt"],"wordFamilyForms":[{"form":"reflect","partOfSpeech":"verb","example":"Students should reflect on their mistakes after each test.","pedagogicallyUseful":true},{"form":"reflection","partOfSpeech":"noun","example":"The diary is a space for reflection on your learning.","pedagogicallyUseful":true,"altExample":"After some reflection, he decided to change his course."},{"form":"reflective","partOfSpeech":"adjective","example":"She wrote a reflective essay about her year abroad.","pedagogicallyUseful":true,"altExample":"The writer’s reflective tone makes the article feel honest."}],"masteryPassages":[{"passageId":"u10_12_reflect_10_passage_1","contextId":"u10_12_reflect_10_gap_1","text":"At the end of every project, the teacher asks us to stop and think. We ____ on what went well and what we could do better next time.","answer":"reflect"},{"passageId":"u10_12_reflect_10_passage_2","contextId":"u10_12_reflect_10_gap_2","text":"Maria studied every evening for months. Her excellent results ____ all the effort she put in.","answer":"reflect"}],"contextDependentParaphrases":[],"wrongParaphrases":["forget quickly","complain loudly","copy exactly"],"misleadingDistractors":["to forget about something quickly","to complain loudly about something","to copy what someone else has done"],"teacherNote":"Verb: to think carefully about something, especially your own experience or learning (reflect on / upon something). Unit 10 uses it for learning and progress; Unit 6 taught it for study habits. A second sense, to show or be a sign of (the results reflect your hard work), is also common. The noun reflection and the adjective reflective are taught in the Word Family pathway."}]'::jsonb,'["reflection","reflective"]'::jsonb,'["reflect on","time to reflect","reflect carefully"]'::jsonb,'live'),
('vocab_performance','performance','noun','how well a person or thing does a piece of work or an activity','[{"senseId":"performance_1","meaning":"how well a person or thing does a piece of work or an activity","acceptedParaphrases":["achievement level","how well someone does something"],"masteryContexts":[{"contextId":"u10_13_performance_meaning","text":"Getting enough sleep can improve your performance at school.","meaning":"how well someone does their work","wrongMeanings":["how much someone spends on study","how often someone visits friends","how far someone travels to work"]},{"contextId":"u10_13_performance_paraphrase","text":"The school choir gave a wonderful performance at the end-of-year concert.","meaning":"an act of singing, dancing or acting for an audience","wrongMeanings":["a rehearsal with no audience","a meeting to plan an event","a test of musical knowledge"]}],"situationDistractors":["A girl chose which subjects to study next year.","A boy spent his free afternoon tidying his room.","A teacher read the school rules to the new students.","A boy chose a new phone case.","A girl packed her bag for school.","A family decided where to go on holiday."],"gapDistractors":[{"contextId":"u10_13_performance_gap_1","answer":"performance","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_13_performance_gap_2","answer":"performance","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_13_performance_gap_3","answer":"performance","wrong":["loneliness","recreation","literacy"]}],"spellingErrors":["performence","preformance","performanse","perfomance","performace","performanc"],"wordFamilyForms":[{"form":"performance","partOfSpeech":"noun","example":"His performance in the exam was excellent.","pedagogicallyUseful":true},{"form":"perform","partOfSpeech":"verb","example":"The students will perform a play at the end of term.","pedagogicallyUseful":true,"altExample":"Students who perform well in the mock exam can join the advanced class."},{"form":"performer","partOfSpeech":"noun","example":"The street performer juggled five balls at once.","pedagogicallyUseful":true,"altExample":"Every performer in the show was under eighteen."}],"masteryPassages":[{"passageId":"u10_13_performance_passage_1","contextId":"u10_13_performance_gap_1","text":"Sam slept for only four hours before the exam. Not surprisingly, his ____ was much worse than usual.","answer":"performance"},{"passageId":"u10_13_performance_passage_2","contextId":"u10_13_performance_gap_2","text":"The orchestra practised for months. On the night of the concert, the audience gave their ____ a standing ovation.","answer":"performance"}],"contextDependentParaphrases":[],"wrongParaphrases":["attendance level","how often someone attends","how much someone earns"],"misleadingDistractors":["the reason why someone chose a subject","the amount of free time a student has","the rules a school expects students to follow"],"teacherNote":"Noun: how well someone does a task or activity (academic performance, performance in an exam, improve your performance). Second common sense: a show in front of an audience (a performance of a play). The verb perform and the noun performer are taught in the Word Family pathway."}]'::jsonb,'["perform","performer"]'::jsonb,'["academic performance","improve your performance","a strong performance"]'::jsonb,'live'),
('vocab_confidence_10','confidence','noun','the feeling that you can do something well or that you can trust someone or something','[{"senseId":"confidence_10_1","meaning":"the feeling that you can do something well or that you can trust someone or something","acceptedParaphrases":["self-belief","a feeling that you can succeed"],"masteryContexts":[{"contextId":"u10_14_confidence_10_meaning","text":"After failing his driving test twice, Sam lost all his confidence.","meaning":"the belief that you can do something well","wrongMeanings":["the fear of failing an exam","the wish to give up driving","the money paid for lessons"]},{"contextId":"u10_14_confidence_10_paraphrase","text":"Parents have great confidence in the new head teacher.","meaning":"trust in someone’s ability","wrongMeanings":["doubt about someone’s ability","anger at someone’s decisions","fear of someone’s power"]}],"situationDistractors":["A girl’s hands shook as she waited for her exam to start.","A boy hid at the back of the class so the teacher would not ask him a question.","A student refused to answer because she was sure she would be wrong.","A girl felt sick with worry before her speech.","A boy refused to try because he expected to fail.","A student stayed silent because she feared being laughed at."],"gapDistractors":[{"contextId":"u10_14_confidence_10_gap_1","answer":"confidence","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_14_confidence_10_gap_2","answer":"confidence","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_14_confidence_10_gap_3","answer":"confidence","wrong":["loneliness","recreation","industry"]}],"spellingErrors":["confidance","confedence","confidense","confidnce","conffidence","confindence"],"wordFamilyForms":[{"form":"confidence","partOfSpeech":"noun","example":"Practice gave her more confidence in speaking.","pedagogicallyUseful":true},{"form":"confident","partOfSpeech":"adjective","example":"He felt confident before the interview.","pedagogicallyUseful":true,"altExample":"I am confident that our team will win."},{"form":"confidently","partOfSpeech":"adverb","example":"She answered every question confidently.","pedagogicallyUseful":true,"altExample":"The new student walked confidently into the classroom."}],"masteryPassages":[{"passageId":"u10_14_confidence_10_passage_1","contextId":"u10_14_confidence_10_gap_1","text":"At first, Ana was too shy to speak in class. After joining the drama club, she gained the ____ to give her opinion in front of everyone.","answer":"confidence"},{"passageId":"u10_14_confidence_10_passage_2","contextId":"u10_14_confidence_10_gap_2","text":"The team lost every match last season. The new coach is working hard to rebuild the players’ ____.","answer":"confidence"}],"contextDependentParaphrases":[],"wrongParaphrases":["nervousness","loneliness","jealousy"],"misleadingDistractors":["a feeling of worry before a test","a strong wish to be alone","the habit of copying other people"],"teacherNote":"Noun: the feeling that you can do things well, or trust in someone (gain / lose / build confidence, confidence in someone). Unit 10 uses it for learning and speaking; Units 6 and 7 taught it for study and interviews. The adjective confident and the adverb confidently are taught in the Word Family pathway."}]'::jsonb,'["confident","confidently"]'::jsonb,'["build confidence","lose confidence","speak with confidence"]'::jsonb,'live'),
('vocab_contribute_10','contribute','verb','to give something, such as ideas, money or effort, to help achieve something','[{"senseId":"contribute_10_1","meaning":"to give something, such as ideas, money or effort, to help achieve something","acceptedParaphrases":["give","add your part to"],"masteryContexts":[{"contextId":"u10_15_contribute_10_meaning","text":"All students are expected to contribute to class discussions.","meaning":"to give ideas or effort to help","wrongMeanings":["to take ideas away from others","to refuse to give an opinion","to repeat what others have said"]},{"contextId":"u10_15_contribute_10_paraphrase","text":"Too much screen time can contribute to poor concentration.","meaning":"to be one of the causes of something","wrongMeanings":["to prevent something from happening","to cure something completely","to measure something accurately"]}],"situationDistractors":["A boy sat silently and let the others do all the work.","A girl took the last biscuit and gave nothing back.","A student left the group meeting before it started.","A boy ate the food without helping to cook it.","A girl watched the others build the model.","A student skipped every group meeting."],"gapDistractors":[{"contextId":"u10_15_contribute_10_gap_1","answer":"contribute","wrong":["succeed","reflect","evaluate"]},{"contextId":"u10_15_contribute_10_gap_2","answer":"contribute","wrong":["succeed","reflect","develop"]},{"contextId":"u10_15_contribute_10_gap_3","answer":"contribute","wrong":["succeed","evaluate","communicate"]}],"spellingErrors":["contribut","contribbute","contrybute","contributte","kontribute","contributt"],"wordFamilyForms":[{"form":"contribute","partOfSpeech":"verb","example":"Everyone should contribute ideas to the discussion.","pedagogicallyUseful":true},{"form":"contribution","partOfSpeech":"noun","example":"Thank you for your contribution to the project.","pedagogicallyUseful":true,"altExample":"Parents made a generous contribution to the library fund."},{"form":"contributor","partOfSpeech":"noun","example":"Each contributor to the magazine is a student.","pedagogicallyUseful":true,"altExample":"The biggest contributor to the charity was a local business."}],"masteryPassages":[{"passageId":"u10_15_contribute_10_passage_1","contextId":"u10_15_contribute_10_gap_1","text":"In group work, nobody should sit back and let others do everything. Every member is expected to ____ ideas.","answer":"contribute"},{"passageId":"u10_15_contribute_10_passage_2","contextId":"u10_15_contribute_10_gap_2","text":"Many things can affect how well you sleep. Late-night screen time can ____ to poor sleep.","answer":"contribute"}],"contextDependentParaphrases":[],"wrongParaphrases":["take","refuse","remove"],"misleadingDistractors":["to take something away from a group","to refuse to take part in something","to watch others without helping"],"teacherNote":"Verb: to give ideas, money or effort to help (contribute to something, contribute ideas); also to be one of the causes (contribute to a problem). Stress on the second syllable. Unit 10 uses it for group work and learning; Unit 7 taught it for teamwork at work. The nouns contribution and contributor are taught in the Word Family pathway."}]'::jsonb,'["contribution","contributor"]'::jsonb,'["contribute to","contribute ideas","contribute money"]'::jsonb,'live'),
('vocab_condition','condition','noun','something that must happen or be true before something else can happen; also the state that something or someone is in','[{"senseId":"condition_1","meaning":"something that must happen or be true before something else can happen; also the state that something or someone is in","acceptedParaphrases":["requirement","state"],"masteryContexts":[{"contextId":"u10_16_condition_meaning","text":"You can borrow the laptop on condition that you return it by Friday.","meaning":"something that must happen first","wrongMeanings":["something given as a reward afterwards","something you can ignore","something that happens by chance"]},{"contextId":"u10_16_condition_paraphrase","text":"Although the car is twenty years old, it is still in excellent condition.","meaning":"the state that something is in","wrongMeanings":["the price that something costs","the age that something is","the place where something is kept"]}],"situationDistractors":["A student received a prize for being the best in her class.","A boy explained that his bus had been late.","The class had a ten-minute break between maths and science.","A girl got a medal for winning a race.","A boy apologised for forgetting his homework.","The class went outside for lunch."],"gapDistractors":[{"contextId":"u10_16_condition_gap_1","answer":"condition","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_16_condition_gap_2","answer":"condition","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_16_condition_gap_3","answer":"condition","wrong":["loneliness","recreation","industry"]}],"spellingErrors":["condision","conditon","condittion","cundition","condtion","conditoin"],"masteryPassages":[{"passageId":"u10_16_condition_passage_1","contextId":"u10_16_condition_gap_1","text":"Dad said I could go to the concert. However, there was one ____: I had to be home by eleven.","answer":"condition"},{"passageId":"u10_16_condition_passage_2","contextId":"u10_16_condition_gap_2","text":"My grandfather’s old bicycle is fifty years old. He has looked after it so well that it is still in perfect ____.","answer":"condition"}],"contextDependentParaphrases":[],"wrongParaphrases":["reward","excuse","break"],"misleadingDistractors":["a reward given after an exam","a reason for being late","a short break between lessons"],"teacherNote":"Noun: (1) something that must be true before something else happens (on condition that, a condition of entry); (2) the state of something (in good / bad condition); (3) plural, the situation people live or work in (working conditions). The adjective conditional is a separate Unit 10 target."}]'::jsonb,'[]'::jsonb,'["on condition that","in good condition","working conditions"]'::jsonb,'live'),
('vocab_conditional','conditional','noun','a sentence or clause, often beginning with if, that describes a possible situation and its result','[{"senseId":"conditional_1","meaning":"a sentence or clause, often beginning with if, that describes a possible situation and its result","acceptedParaphrases":["an if-sentence","a sentence about a possible situation and its result"],"masteryContexts":[{"contextId":"u10_17_conditional_meaning","text":"“If I had more time, I would learn Japanese” is an example of the second conditional.","meaning":"a type of if-sentence about an imagined situation","wrongMeanings":["a sentence that reports what someone said","a sentence that gives an order","a sentence that asks a question"]},{"contextId":"u10_17_conditional_paraphrase","text":"In your essay, try to use a conditional to explain what might happen if the plan fails.","meaning":"a sentence that describes a possible situation and its result","wrongMeanings":["a sentence that describes a past habit","a sentence that compares two things","a sentence that lists several facts"]}],"situationDistractors":["A student wrote: “She said that she was tired.”","A teacher asked: “Have you finished your homework?”","A sign said: “Close the door.”","A student wrote: “Yesterday I went to the park.”","A teacher wrote: “Open your books.”","A girl asked: “Is it raining?”"],"gapDistractors":[{"contextId":"u10_17_conditional_gap_1","answer":"conditional","wrong":["intonation","pronunciation","loneliness"]},{"contextId":"u10_17_conditional_gap_2","answer":"conditional","wrong":["intonation","pronunciation","recreation"]},{"contextId":"u10_17_conditional_gap_3","answer":"conditional","wrong":["loneliness","recreation","industry"]}],"spellingErrors":["condisional","conditonal","conditionel","condittional","conditionnal","condtional"],"masteryPassages":[{"passageId":"u10_17_conditional_passage_1","contextId":"u10_17_conditional_gap_1","text":"Look at this example: if I won the lottery, I would travel the world. This sentence is an example of the second ____.","answer":"conditional"},{"passageId":"u10_17_conditional_passage_2","contextId":"u10_17_conditional_gap_2","text":"Our grammar lesson today is about if-sentences. We will start with the first ____, which describes likely future situations.","answer":"conditional"}],"contextDependentParaphrases":[],"wrongParaphrases":["a reported sentence","a yes/no question","a command"],"misleadingDistractors":["a sentence that reports what someone else said","a question that needs only a yes or no answer","a sentence that gives an order"],"teacherNote":"Noun (grammar): a sentence or clause about a possible or imagined situation and its result, usually with if (the zero, first, second and third conditional). Also an adjective (a conditional clause, conditional on). Linked to the noun condition. Students should be able to name and form the main conditionals."}]'::jsonb,'[]'::jsonb,'["the first conditional","the second conditional","use a conditional"]'::jsonb,'live'),
('vocab_preparation','preparation','noun','the work or planning done to get ready for something','[{"senseId":"preparation_1","meaning":"the work or planning done to get ready for something","acceptedParaphrases":["getting ready","planning in advance"],"masteryContexts":[{"contextId":"u10_18_preparation_meaning","text":"The students spent two weeks in preparation for the science fair.","meaning":"work done to get ready","wrongMeanings":["the celebration after the event","the cancellation of the event","the judging of the event"]},{"contextId":"u10_18_preparation_paraphrase","text":"The family spent almost a year on preparation for the wedding.","meaning":"the planning and arrangements made before an event","wrongMeanings":["the cost of the celebration","the guests at the celebration","the memories of the celebration"]}],"situationDistractors":["The head teacher announced the winners of the competition.","A boy was shocked when the fire alarm suddenly rang.","A concert was cancelled because the singer was ill.","A boy forgot about his exam until he arrived at school.","A family celebrated after the wedding.","A girl complained about the result after the competition."],"gapDistractors":[{"contextId":"u10_18_preparation_gap_1","answer":"preparation","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_18_preparation_gap_2","answer":"preparation","wrong":["loneliness","recreation","literacy"]},{"contextId":"u10_18_preparation_gap_3","answer":"preparation","wrong":["loneliness","recreation","intonation"]}],"spellingErrors":["preperation","preparasion","prepration","prepairation","preparaton","preparetion"],"wordFamilyForms":[{"form":"preparation","partOfSpeech":"noun","example":"Good preparation leads to good results.","pedagogicallyUseful":true},{"form":"prepare","partOfSpeech":"verb","example":"We need to prepare for the science test.","pedagogicallyUseful":true,"altExample":"It takes an hour to prepare the room for the exam."},{"form":"prepared","partOfSpeech":"adjective","example":"She felt well prepared for her presentation.","pedagogicallyUseful":true,"altExample":"Always come prepared with a pen and a calculator."}],"masteryPassages":[{"passageId":"u10_18_preparation_passage_1","contextId":"u10_18_preparation_gap_1","text":"The exams start in six weeks. Students who begin their ____ now will feel much calmer on the day.","answer":"preparation"},{"passageId":"u10_18_preparation_passage_2","contextId":"u10_18_preparation_gap_2","text":"The school festival takes months to organise. The students begin their ____ in January, when they start planning the stalls.","answer":"preparation"}],"contextDependentParaphrases":[],"wrongParaphrases":["celebrating afterwards","cancelling at the last minute","complaining later"],"misleadingDistractors":["the results announced after an event","a feeling of surprise when something happens","the act of cancelling an event"],"teacherNote":"Noun: the work of getting ready for something (preparation for an exam, in preparation for, preparations for a festival). Uncountable for the process; plural preparations for the practical tasks. The verb prepare and the adjective prepared are taught in the Word Family pathway."}]'::jsonb,'["prepare","prepared"]'::jsonb,'["in preparation for","careful preparation","exam preparation"]'::jsonb,'live'),
('vocab_employment_10','employment','noun','the situation of having a paid job, or the work that people are paid to do','[{"senseId":"employment_10_1","meaning":"the situation of having a paid job, or the work that people are paid to do","acceptedParaphrases":["paid work","having a job"],"masteryContexts":[{"contextId":"u10_19_employment_10_meaning","text":"Graduates in engineering usually find employment within six months.","meaning":"a paid job","wrongMeanings":["a place at university","a long holiday","a scholarship to study abroad"]},{"contextId":"u10_19_employment_10_paraphrase","text":"The government wants to increase employment in poorer regions.","meaning":"the number of people who have paid work","wrongMeanings":["the number of tourists who visit","the number of houses that are built","the number of people who own cars"]}],"situationDistractors":["A student spent the summer reading novels at home.","A man stayed in hospital for a week after an accident.","A girl played the guitar with friends on Saturday mornings.","A boy played video games all summer.","A woman retired and moved to the coast.","A student studied full-time at college."],"gapDistractors":[{"contextId":"u10_19_employment_10_gap_1","answer":"employment","wrong":["loneliness","pronunciation","intonation"]},{"contextId":"u10_19_employment_10_gap_2","answer":"employment","wrong":["loneliness","pronunciation","intonation"]},{"contextId":"u10_19_employment_10_gap_3","answer":"employment","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["employmant","imployment","employement","emploiment","emplyment","employmment"],"wordFamilyForms":[{"form":"employment","partOfSpeech":"noun","example":"Many graduates find employment quickly.","pedagogicallyUseful":true},{"form":"employ","partOfSpeech":"verb","example":"The hotel will employ ten students this summer.","pedagogicallyUseful":true,"altExample":"Local shops employ many students at weekends."},{"form":"employer","partOfSpeech":"noun","example":"My employer pays for my training course.","pedagogicallyUseful":true,"altExample":"Every employer wants staff who can communicate well."}],"masteryPassages":[{"passageId":"u10_19_employment_10_passage_1","contextId":"u10_19_employment_10_gap_1","text":"When the factory closed, hundreds of workers lost their jobs. Many had to move to the city to find new ____.","answer":"employment"},{"passageId":"u10_19_employment_10_passage_2","contextId":"u10_19_employment_10_gap_2","text":"Engineering graduates rarely struggle to find work. Most are in full-time ____ within six months of leaving university.","answer":"employment"}],"contextDependentParaphrases":[],"wrongParaphrases":["unpaid study","early retirement","a holiday abroad"],"misleadingDistractors":["time spent studying at university","money given to people who are ill","a hobby that people enjoy at weekends"],"teacherNote":"Noun: having a paid job, or paid work in general (find employment, full-time / part-time employment, employment opportunities). Uncountable. Unit 10 uses it to link education with future work; Unit 8 taught it in the world of work. The verb employ and the nouns employer, employee and unemployment are taught in the Word Family pathway."}]'::jsonb,'["employ","employer"]'::jsonb,'["find employment","full-time employment","employment opportunities"]'::jsonb,'live'),
('vocab_career','career','noun','the series of jobs that a person does in a particular type of work, usually over a long time','[{"senseId":"career_1","meaning":"the series of jobs that a person does in a particular type of work, usually over a long time","acceptedParaphrases":["professional life","working life"],"masteryContexts":[{"contextId":"u10_20_career_meaning","text":"The school offers career advice to help students choose the right path.","meaning":"the type of work someone plans to do for a long time","wrongMeanings":["the subjects someone studies at school","the hobbies someone enjoys at weekends","the places someone visits on holiday"]},{"contextId":"u10_20_career_paraphrase","text":"During his long career as a footballer, he played for five different clubs.","meaning":"the period of time someone spends working in a profession","wrongMeanings":["the time someone spends training each day","the money someone earns in one season","the injuries someone has during a match"]}],"situationDistractors":["A family spent a week on holiday in the mountains.","A boy felt nervous on his first day at a new school.","A woman went fishing every Sunday morning.","A girl spent one afternoon helping at a jumble sale.","A boy had a day off school with a cold.","A family visited a museum on a rainy day."],"gapDistractors":[{"contextId":"u10_20_career_gap_1","answer":"career","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_20_career_gap_2","answer":"career","wrong":["literacy","loneliness","pronunciation"]},{"contextId":"u10_20_career_gap_3","answer":"career","wrong":["loneliness","literacy","intonation"]}],"spellingErrors":["carrer","carreer","carier","creer","careeer","carear"],"masteryPassages":[{"passageId":"u10_20_career_passage_1","contextId":"u10_20_career_gap_1","text":"Ahmed has loved animals since he was a child. He hopes to have a long ____ as a vet.","answer":"career"},{"passageId":"u10_20_career_passage_2","contextId":"u10_20_career_gap_2","text":"The famous actor retired last year. During his fifty-year ____, he appeared in more than a hundred films.","answer":"career"}],"contextDependentParaphrases":[],"wrongParaphrases":["short break","school day","weekend hobby"],"misleadingDistractors":["a short holiday between two jobs","the first day at a new school","a hobby done only at weekends"],"teacherNote":"Noun: the jobs a person does over a long period in one type of work (a career in law, a career change, career advice). Countable. Stress on the second syllable. Boundary: a job is a particular position; a career is a long-term path. Common error: confusing career with course (a course of study)."}]'::jsonb,'[]'::jsonb,'["a career in","career advice","a successful career"]'::jsonb,'live')
